-- Full H1/H2 explanation replacement after 325-question visual source audit.
-- PASS explanations are byte-identical.  FAIL explanations are exact, hash-bound
-- transcriptions from the paired source-analysis crop.  The immutable v2 revision
-- contract binds the student explanation and both private source assets.
-- Student rendering is image-primary.  The legacy OCR fallback contains page
-- headers, watermarks and broken formula glyphs, so every replacement row gets
-- a question-specific source-free fallback with page furniture and broken PDF
-- glyphs removed.  The exact original remains the hash-bound private image.
-- This migration does not modify H3, REVIEW history/plans, or the independent quiz.

begin;

select pg_catalog.pg_advisory_xact_lock(
  pg_catalog.hashtextextended('chem-source-original-release', 0)
);
select pg_catalog.pg_advisory_xact_lock(
  pg_catalog.hashtextextended('chem-h3-original-release', 0)
);

