b 点所得溶液中：c(H2SO3)＋c(H\n＋)＝c(SO2－\n3 )＋c(OH\n－)\nC.c 点所得溶液中：c(Na\n＋)>3c(HSO\n－\n3 )\nD.d 点所得溶液中：c(Na\n＋)>c(HSO\n－\n3 )>c(SO2－\n3 )","expected_options":["a 点所得溶液中：2c(H2SO3)＋c(SO2－ 3 )<0.1 mol·L －1","b 点所得溶液中：c(H2SO3)＋c(H ＋)＝c(SO2－ 3 )＋c(OH －)","c 点所得溶液中：c(Na ＋)>3c(HSO － 3 )","d 点所得溶液中：c(Na ＋)>c(HSO － 3 )>c(SO2－ 3 )"],"expected_content_fingerprint":"47be6bdad2a0b256f83ed705848e7621ed21548c0dfc2b31eecaf506a2dd9ce3","audit_status":"FAIL","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/09586db1ea064bed/13cb6fef23518f19ee30b37fea68175d/question/r245be48b2999","alt":"苏教版高中化学原题已知pKa＝－lg Ka，25 ℃时，H2SO3原题题面","sha256":"fc5b3e521378117a3b42a7b2b5152569677b256fafa0e07dddd153c088d96ab2","width":1055,"height":523},{"kind":"analysis_image","path":"h2orig/09586db1ea064bed/13cb6fef23518f19ee30b37fea68175d/analysis/r245be48b2999","alt":"苏教版高中化学原题已知pKa＝－lg Ka，25 ℃时，H2SO3原题解析","sha256":"163ee9c3846c768d1e7179d6bbacfe0cac7d98cdc530b493cfaa17efc4f51480","width":1055,"height":2091}],"question_asset_sha256":"fc5b3e521378117a3b42a7b2b5152569677b256fafa0e07dddd153c088d96ab2","analysis_asset_sha256":"163ee9c3846c768d1e7179d6bbacfe0cac7d98cdc530b493cfaa17efc4f51480","expected_revision_token":"c29eff61ca1411b38ce0c48b82e8b23303aa41115f54b69a452937b3a9a1eef3","expected_item_sha256":"f6fb454bbf95375eade73363879e7a0c5f03936256af143f1808edea4f10e130","source_pdf_sha256":"c5bd2159a7716277d39ec6313506bb72dc520a64e3187fd2685e067ddd30fc76","question_png_sha256":"1a9b356664552291aca227da05e308a2199e1370ac6eb383977ce1dc74984767","analysis_png_sha256":"6c91ea2b05114b70257b64d55885b6af762a2351ab5269fc297f14bf4b2900a3"},{"source_manifest_id":"H2_PH_HYDRO-afaaf7a97fc3eb86","canonical_source_id":"--:H2_PH_HYDRO-afaaf7a97fc3eb86","grade_band":"高二","skill_id":"H2_PH_HYDRO","old_question_id":"QH2O_C855000A00C29EE3_BEBB2232F9357AFF_R761DC1B48D41","new_question_id":"QH2O_C855000A00C29EE3_839D9010836DFE53_R245BE48B2999","correct_option":1,"baseline_