b73a1d49edfc2","audit_status":"PASS","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/2f4f7b9561b53cea/9fff4b7da356ce7e793aee786174a8b3/question/r245be48b2999","alt":"苏教版高中化学原题6原题题面","sha256":"9be90e927fc6dd3cee8e5f9ba8fb32dca95ca3040dcd2d7017174e846770997d","width":1055,"height":677},{"kind":"analysis_image","path":"h2orig/2f4f7b9561b53cea/9fff4b7da356ce7e793aee786174a8b3/analysis/r245be48b2999","alt":"苏教版高中化学原题6原题解析","sha256":"aafb1fe232e144c77cb665d63dcfed75eaa040886ab5263de143df4205f87edd","width":1055,"height":334}],"question_asset_sha256":"9be90e927fc6dd3cee8e5f9ba8fb32dca95ca3040dcd2d7017174e846770997d","analysis_asset_sha256":"aafb1fe232e144c77cb665d63dcfed75eaa040886ab5263de143df4205f87edd","expected_revision_token":"b3125da160a58f2d88a0a1048affe2be772c1bbeef55b08c218a68d8c92df773","expected_item_sha256":"54d7c24ce73a95bfe90c8b99d116b3edad69a0e793626a074c7375470ee5ea66","source_pdf_sha256":"43bd8beda5969e085fedf91c74c77d7f6cb48851e1a1092a2019f71054d37ef5","question_png_sha256":"4a3a31397a7552ee66965a7ed8feec53c2e39bdaa1246453a3f888652213b348","analysis_png_sha256":"5931d923ad014f3f3a59ac92de277e1c5fb4227bfc8e4e9fabc194b89367fea7"},{"source_manifest_id":"H2_THERMO-d4eb6bb6f2c12b52","canonical_source_id":"--:H2_THERMO-d4eb6bb6f2c12b52","grade_band":"高二","skill_id":"H2_THERMO","old_question_id":"QH2O_804D2901A8CE23B2_633AC474FD876CD5_R761DC1B48D41","new_question_id":"QH2O_804D2901A8CE23B2_544F97016147B46B_R245BE48B2999","correct_option":3,"baseline_explanation_sha256":"379ca2d82fead02788be421ed8ac37cb882c2acd3ed28cd957dbe6159c942741","expected_explanation_sha256":"fdf03217f7cc24899836d8059ba73aec4977655df104596d15751a821169b92e","expected_explanation":"A．若CO的标准燃烧热为ΔH₃，则CO(g)＋1/2O₂(g)→CO₂(g)。用该式减去反应①可得H₂(g)＋1/2O₂(g)→H₂O(g)，ΔH＝ΔH₃－ΔH₁；但氢气的标准燃烧热要求生成稳定状态的H₂O(l)，所以该ΔH不能表示氢气的标准燃烧热，A错误。\nB．用反应②减去反应①，得CH₄(g)＋CO₂(g)→2CO(g)＋2H₂(g)，ΔH＝ΔH₂－ΔH₁，不是ΔH₁－ΔH₂，B错误。\nC．反应物总能量低于生成物总能量时反应吸热，所以ΔH₂＞0，C错误。\nD．设CO、H₂完全燃烧生成气态产物的焓变分别为ΔH₃、ΔH₄。后者放热更多且二者均为负值，所以ΔH₃＞ΔH₄；由ΔH₁＝ΔH₃－ΔH₄得ΔH₁＞0，D正确。\n故选D。","expected_stem":"已知：\n①CO（g）＋H2O（g）===CO2（g）＋H2（g）\nΔH1\n②CH4（g）＋H2O（g）===CO（g）＋3H2（g）\nΔH2\n下列推断正确的是（\n）\nA.若CO 的标准燃烧热为ΔH3，则H2 的标准燃烧热为ΔH3－ΔH1\nB.反应CH4（g）＋CO2（g）===2CO（g）＋2H2（g）的ΔH＝ΔH1－ΔH2\nC.若反应②的反应物总能量低于生成物总能量，则ΔH2<0\nD.若等物质的量的CO 和H2 完全燃烧生成气态产物时后者放热更多，则ΔH1＞0","expected_options":["若CO 的标准燃烧热为ΔH3，则H2 的标准燃烧热为ΔH3－ΔH1","反应CH4（g）＋CO2（g）===2CO（g）＋2H2（g）的ΔH＝ΔH1－ΔH2","若反应②的反应物总能量低于生成物总能量，则ΔH2<0","若等物质的量的CO 和H2 完全燃烧生成气态产物时后者放热更多，则ΔH1＞0"],"expected_content_fingerprint":"c956b9a7b529af2a53294e554b91840e52a112a189367ddee33309168f9fd2cd","audit_status":"FAIL","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/804d2901a8ce23b2/ba095a0faed50f3d30aebe040912d326/question/r245be48b2999","alt":"苏教版高中化学原题5原题题面","sha256":"e0978b1d03ff31560c3b59800feb65ca2e3c972a3f799f4ec35b58d80667453e","width":1055,"height":380},{"kind":"analysis_image","path":"h2orig/804d2901a8ce23b2/ba095a0faed50f3d30aebe040912d326/analysis/r245be48b2999","alt":"苏教版高中化学原题5原题解析","sha256":"4ec89d6f51f73dfa76bd5b0df6f54723bd9ac487433f28869c3028f7fad205bb","width":1055,"height":535}],"question_asset_sha256":"e0978b1d03ff31560c3b59800feb65ca2e3c972a3f799f4ec35b58d80667453e","analysis_asset_sha256":"4ec89d6f51f73dfa76bd5b0df6f54723bd9ac487433f28869c3028f7fad205bb","expected_revision_token":"2902e382abbd85a8353d34366a2a003a05a155d53b8ea34998d04aeed61eab5b","expected_item_sha256":"d8959aa6ee65f73849bcfdfe25187b252b71543893ed475001af435048945422","source_pdf_sha256":"43bd8beda5969e085fedf91c74c77d7f6cb48851e1a1092a2019f71054d37ef5","question_png_sha256":"f4cb0ffeeb03e3cc4e9dd012c5973cd889bafb2314f5d766d678fa97634eb1f2","analysis_png_sha256":"23e5111786b2efb829e767f0f0139f8345f41b7ad0cb014601d237581a225f0b"},{"source_manifest_id":"H2_THERMO-e8d8d0176e22655e","canonical_source_id":"--:H2_THERMO-e8d8d0176e22655e","grade_band":"高二","skill_id":"H2_THERMO","old_question_id":"QH2O_68C3C4B39C105767_5BBF8F3414555EE6_R761DC1B48D41","new_question_id":"QH2O_68C3C4B39C105767_88F7943EABB08ECF_R245BE48B2999","correct_option":1,"baseline_explanation_sha256":"246e3694808f2b1dff0843313df949fc461bf395945f6084d0844fcc8fe49b86","expected_explanation_sha256":"26d2ea25d81618c45784f0b74a923f2bd23328f6564eb35e40e2f4af0336db6a","expected_explanation":"A．过程①、③是断键形成原子，均吸热；过程②、④是原子成键形成分子，均放热，不是四步都放热，A错误。\nB．①、②、③、④的焓变依次为＋a、－c、＋b、－d kJ·mol⁻¹。四式相加后除以2得到目标反应，所以m＝1/2(a＋b－c－d)，B正确。\nC．该式没有同时正确计入四步的吸、放热符号，C错误。\nD．该式把成键放出的能量c、d写成正项，并把断键吸收的能量a、b写成负项，符号相反，D错误。\n故选B。","expected_stem":"某硝酸厂处理尾气中NO 的方法是在催化剂存在下，用H2\n将NO 还原为N2，其热化学方程式为NO（g）＋H2（g）===1\n2N2（g）＋H2O（g）\nΔH＝m kJ·mol\n－1，其能量变化过程如下（其中a、b、c、d 均为正值）：\n下列说法正确的是（\n）\nA.过程①、②、③、④都是放热过程\nB.m＝1\n2（a＋b－c－d）\nC.m＝1\n2（c＋a－d－b）\nD.m＝1\n2（c＋d－a－b）","expected_options":["过程①、②、③、④都是放热过程","m＝1 2（a＋b－c－d）","m＝1 2（c＋a－d－b）","m＝1 2（c＋d－a－b）"],"expected_content_fingerprint":"25d49b82dbecc6cb9dc434d20a94ce2a7f4005c52b535c47cc4a840280598c85","audit_status":"FAIL","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/68c3c4b39c105767/e9cd442c24c30c438bffc90f346083f6/question/r245be48b2999","alt":"苏教版高中化学原题9原题题面","sha256":"7a4fc89421bb912f86c9b51bcec2bc4648471faa4ae087039174ecf917f58580","width":1055,"height":621},{"kind":"analysis_image","path":"h2orig/68c3c4b39c105767/e9cd442c24c30c438bffc90f346083f6/analysis/r245be48b2999","alt":"苏教版高中化学原题9原题解析","sha256":"c22b72797a1dca54c1c9900c515db1b47c9105b4546ddd29b6dbf7fffe17c224","width":1055,"height":435}],"question_asset_sha256":"7a4fc89421bb912f86c9b51bcec2bc4648471faa4ae087039174ecf917f58580","analysis_asset_sha256":"c22b72797a1dca54c1c9900c515db1b47c9105b4546ddd29b6dbf7fffe17c224","expected_revision_token":"4ebd5b370872549eb58a9d3795ca5133738d3ead75734b0a264f8405baf6b5ff","expected_item_sha256":"4b336dc7153014740b85a151d849fe01ac037974c75b91b92c54f2e1fddc814e","source_pdf_sha256":"43bd8beda5969e085fedf91c74c77d7f6cb48851e1a1092a2019f71054d37ef5","question_png_sha256":"ad1ddc70fd008a2b4cc4530c753d433cc445907861f403a912b18c15a3ecbabd","analysis_png_sha256":"3dd08a8ccf4b8c5361203904f661e453ab70e3dbe83f439a39112aeb8ccd6808"},{"source_manifest_id":"H2_THERMO-eadb929d48691230","canonical_source_id":"--:H2_THERMO-eadb929d48691230","grade_band":"高二","skill_id":"H2_THERMO","old_question_id":"QH2O_A46EAA22DBA67784_4AF9B7DB8AA8C805_R761DC1B48D41","new_question_id":"QH2O_A46EAA22DBA67784_A52678208C6BA28B_R245BE48B2999","correct_option":3,"baseline_explanation_sha256":"9f4527b67395fd75b395d98e19c99b862d59d03d4d8153303491055a7c35f20f","expected_explanation_sha256":"9f4527b67395fd75b395d98e19c99b862d59d03d4d8153303491055a7c35f20f","expected_explanation":"A．灰锡和白锡是锡元素形成的两种不同单质，互为同素异形体，A 正确；\nB．根据Sn（s，灰）>13.2 ℃\n<13.2 ℃Sn（s，白）可知，温度低于13.2 ℃\n，白锡会转变\n为灰锡，所以在标准状况下（0 ℃，101 kPa），锡以灰锡状态存在，B 正确；\nC．反应①是活泼金属和酸发生的置换反应，是放热反应，C 正确；\nD．根据反应③Sn\n－1。可知，由灰锡变为白锡\n（s，灰）>13.2 ℃\n<13.2 ℃Sn（s，白）\nΔH3＝＋2.1 kJ·mol\n会吸收热量，所以反应①放出的热量大于反应②，但由于反应①和②都是放热反\n应，ΔH 为负值，所以ΔH1<ΔH2，D 错误。","expected_stem":"已知：\n①Sn（s，白）＋2HCl（aq）===SnCl2（aq）＋H2（g）\nΔH1\n②Sn（s，灰）＋2HCl（aq）===SnCl2（aq）＋H2（g）\nΔH2\n③Sn（s，灰）>13.2 ℃\n<13.2 ℃Sn（s，白）\n－1\nΔH2＝＋2.1 kJ·mol\n下列说法不正确的是（\n）\nA.灰锡与白锡互为同素异形体\nB.锡在标准状况下以灰锡状态存在\nC.反应①是放热反应\nD.ΔH1>ΔH2","expected_options":["灰锡与白锡互为同素异形体","锡在标准状况下以灰锡状态存在","反应①是放热反应","ΔH1>ΔH2"],"expected_content_fingerprint":"af7d406819aff619ae73601e139b50603f4224e409690216fc4ac808e39dd505","audit_status":"PASS","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/a46eaa22dba67784/e942663f8fe71b6c8144f4f473059c2f/question/r245be48b2999","alt":"苏教版高中化学原题4原题题面","sha256":"29a081d8108da0d9c618ae2a81965b137c04c511f7a78bc2efe17c56fed59a89","width":1055,"height":490},{"kind":"analysis_image","path":"h2orig/a46eaa22dba67784/e942663f8fe71b6c8144f4f473059c2f/analysis/r245be48b2999","alt":"苏教版高中化学原题4原题解析","sha256":"bebabdbdef9b62dbf3679a0cb85ab4afcc18314050dd307603c45e65ee073ca7","width":1055,"height":412