6c5f15c986/2275558cd370684c1574edf82bc43813/analysis/r245be48b2999","alt":"苏教版高中化学原题3原题解析","sha256":"412252ac11008c061b555b0e709383d51851925ff3d0b67000599d88bfb914e0","width":1055,"height":475}],"question_asset_sha256":"5d9ec974997f640402e76e8e58d05a205718eeab7a5fd52007df884fd25bcabe","analysis_asset_sha256":"412252ac11008c061b555b0e709383d51851925ff3d0b67000599d88bfb914e0","expected_revision_token":"1976f69313f71bfce17ea10377efab3a5ff9949a212de8c1af9e6782f430bffe","expected_item_sha256":"cc228cd54a6f06be2372ed84431139cf44d76df444fcadb405920cf04af341e4","source_pdf_sha256":"1f43e3800520493d33ea368192d9402e19135115e6ba17639826216f81595943","question_png_sha256":"a5dcb6723e76725cff64a3f8528210817af57bcbaa2de61bc638a7289961bba4","analysis_png_sha256":"8809341cd5685588067651e885903d4c35c4e1e4fe10d1473958cbdcf5f44c51"},{"source_manifest_id":"H2_WEAK-f8e447fd573d6be7","canonical_source_id":"--:H2_WEAK-f8e447fd573d6be7","grade_band":"高二","skill_id":"H2_WEAK","old_question_id":"QH2O_8C297DFD9F670A57_0CA37570F9921352_R761DC1B48D41","new_question_id":"QH2O_8C297DFD9F670A57_B22CDFE5FC9330F9_R245BE48B2999","correct_option":1,"baseline_explanation_sha256":"df14d48783ca92de266f3c8776038924520bbeb328f8b6e5556052f81976ea21","expected_explanation_sha256":"df14d48783ca92de266f3c8776038924520bbeb328f8b6e5556052f81976ea21","expected_explanation":"A．较强酸可以制取较弱酸。由三个反应可得酸性HF＞HNO₂＞HCN，因此HF的电离常数最大，为7.2×10⁻⁴，A正确。\nB．HNO₂酸性介于HF和HCN之间，其电离常数应为中间值4.6×10⁻⁴，不是4.9×10⁻¹⁰，B错误。\nC．由NaCN＋HNO₂反应可得HNO₂＞HCN，再由NaNO₂＋HF反应可得HF＞HNO₂，两条反应即可得到HF＞HNO₂＞HCN，C正确。\nD．同温度下酸性越强，电离常数越大，因此K(HCN)＜K(HNO₂)＜K(HF)，D正确。\n故选B。","expected_stem":"已知下面三个数据：7.2×10\n－4、4.6×10\n－4、4.9×10\n的电离常数(25 ℃)，若已知下列反应可以发生：NaCN＋HNO2===HCN＋NaNO2\nNaCN＋HF===HCN＋NaF\nNaNO2＋HF===HNO2＋NaF。由此可判断下列叙述中\n不正确的是(\n)\n－4\nA.K(HF)＝7.2×10\n－10\nB.K(HNO2)＝4.9×10\nC.根据两个反应即可得出一元弱酸的强弱顺序为HF>HNO2>HCN\nD.K(HCN)<K(HNO2)<K(HF)","expected_options":["K(HF)＝7.2×10 －10","K(HNO2)＝4.9×10","根据两个反应即可得出一元弱酸的强弱顺序为HF>HNO2>HCN","K(HCN)<K(HNO2)<K(HF)"],"expected_content_fingerprint":"89964c4f9c58ceb0eeed41e5e42bea191e07d7c49f4690aa3e43157c1e5502c5","audit_status":"PASS","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/8c297dfd9f670a57/6001f324bc9104b942f4d7258c982557/question/r245be48b2999","alt":"苏教版高中化学原题1原题题面","sha256":"08bea1f000a68b3a542f006088c7832ed15fb64f2f9dadf472463e7ce2cd921f","width":1055,"height":381},{"kind":"analysis_image","path":"h2orig/8c297dfd9f670a57/6001f324bc9104b942f4d7258c982557/analysis/r245be48b2999","alt":"苏教版高中化学原题1原题解析","sha256":"fd9d9064c17b3c2c3dd835de52e238579339e1c9e07d29cedb9f1fef5846d6c8","width":1055,"height":194}],"question_asset_sha256":"08bea1f000a68b3a542f006088c7832ed15fb64f2f9dadf472463e7ce2cd921f","analysis_asset_sha256":"fd9d9064c17b3c2c3dd835de52e238579339e1c9e07d29cedb9f1fef5846d6c8","expected_revision_token":"758513c1e89dec7f3250e612f1e486147cede9ad7e4d6e7120f267d5fdc43877","expected_item_sha256":"b09304dfc6e9e12665bcc10830706e701defb45dffb7e0f67ea92d7519bed030","source_pdf_sha256":"1f43e3800520493d33ea368192d9402e19135115e6ba17639826216f81595943","question_png_sha256":"9a48750246b3259a18cd9d73ea86ee2351eaf53f7e21f4b4df57671a229a4218","analysis_png_sha256":"7c0bb94876707f968605cd86d4911fa9d34070e8cb04ccb8036f4ae9e9d42352"},{"source_manifest_id":"H2_WEAK-fa24846e936c694c","canonical_source_id":"--:H2_WEAK-fa24846e936c694c","grade_band":"高二","skill_id":"H2_WEAK","old_question_id":"QH2O_B4823848D435630F_5087F542E0ED90DC_R761DC1B48D41","new_question_id":"QH2O_B4823848D435630F_87020AD050500E53_R245BE48B2999","correct_option":3,"baseline_explanation_sha256":"e4455bd359a533e982455e1ec113f7677fc91e99268e0e9cd50ef3a8d7fa9abd","expected_explanation_sha256":"e4455bd359a533e982455e1ec113f7677fc91e99268e0e9cd50ef3a8d7fa9abd","expected_explanation":"A．M、N两点pH都为3。由电荷守恒，M点c(A⁻)＝c(H⁺)－c(OH⁻)，N点c(B⁻)＝c(H⁺)－c(OH⁻)，因此二者相等，A正确。\nB．1 mol·L⁻¹ HA溶液pH＝2，近似有c(H⁺)＝c(A⁻)＝10⁻² mol·L⁻¹、c(HA)≈1 mol·L⁻¹，所以Kₐ≈10⁻⁴，B正确。\nC．0.1 mol·L⁻¹ NaA与0.1 mol·L⁻¹ HA组成等浓度的弱酸及其盐混合液，c(H⁺)约为Kₐ＝10⁻⁴ mol·L⁻¹，pH约为4，小于7，C正确。\nD．稀释不改变酸的物质的量，M、P两点所含一元酸的物质的量相等；完全中和时消耗等浓度NaOH的体积相等，不是P＞M，D错误。\n故选D。","expected_stem":"室温时，1 mol·L\n－1 的HA 溶液和1 mol·L\n－1 的HB 溶液，起始时的体积均为V0，\n分别向两溶液中加水稀释，所得曲线如图所示。下列说法中错误的是(\n)\nA.M 点溶液中c(A\n－)等于N 点\n溶液中c(B\n－)\n－4\nB.HA 的电离常数约为10\nC.浓度均为0.1 mol·L\n－1 的NaA 和HA 混合溶液的pH<7\nD.M、P 两点的溶液分别用等浓度的NaOH 溶液中和，消耗的NaOH 溶液体积：\nP>M","expected_options":["M 点溶液中c(A －)等于N 点 溶液中c(B －) －4","HA 的电离常数约为10","浓度均为0.1 mol·L －1 的NaA 和HA 混合溶液的pH<7","M、P 两点的溶液分别用等浓度的NaOH 溶液中和，消耗的NaOH 溶液体积： P>M"],"expected_content_fingerprint":"c476d0dc72e428b3371b52c268bf24f2298dc8731aeec7495bf3ed8cd9400ed4","audit_status":"PASS","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/b4823848d435630f/4aa7e50f38a85858ba489de4dabab6d7/question/r245be48b2999","alt":"苏教版高中化学原题3原题题面","sha256":"43748c2c89726a7ec20c59f7a4c342dfa9e3e9aeaec0d20f46675f7a37851789","width":1055,"height":493},{"kind":"analysis_image","path":"h2orig/b4823848d435630f/4aa7e50f38a85858ba489de4dabab6d7/analysis/r245be48b2999","alt":"苏教版高中化学原题3原题解析","sha256":"e101627547bed463d2e7e17530a414a83f0b68e592ac352911a0565cf4024073","width":1055,"height":1312}],"question_asset_sha256":"43748c2c89726a7ec20c59f7a4c342dfa9e3e9aeaec0d20f46675f7a37851789","analysis_asset_sha256":"e101627547bed463d2e7e17530a414a83f0b68e592ac352911a0565cf4024073","expected_revision_token":"6779b415e0b9fa750c8cbdcfe43b04f54f246054e622bc2beb708e759009e1c6","expected_item_sha256":"6132863cb1575cbd9c621985220ccc943d3b62c3495ddb9380992beaff8c902e","source_pdf_sha256":"1f43e3800520493d33ea368192d9402e19135115e6ba17639826216f81595943","question_png_sha256":"0c5d1db8d889335cad09d3e90a7d88d0fb2fdfcb8d04fcb3c82d511e2c85755e","analysis_png_sha256":"9d218c395d9a8f03b690157111afbf3ceec5884d385a768387fb68403a1c1f64"},{"source_manifest_id":"H2_WEAK-ff6cdf012f6ed33b","canonical_source_id":"--:H2_WEAK-ff6cdf012f6ed33b","grade_band":"高二","skill_id":"H2_WEAK","old_question_id":"QH2O_A9412D2FEF20A8E3_EF6EBB9033E1D38D_R761DC1B48D41","new_question_id":"QH2O_A9412D2FEF20A8E3_05143117BEFA78BC_R245BE48B2999","correct_option":2,"baseline_explanation_sha256":"b8af25cbf6c9cfc5adae0e1a840b230243c2fbd05d08c7c5646eb0f995f2ef73","expected_explanation_sha256":"b8af25cbf6c9cfc5adae0e1a840b230243c2fbd05d08c7c5646eb0f995f2ef73","expected_explanation":"A．同一温度下，同一种弱酸HX的电离常数只与温度有关，因此K₁＝K₂＝K₃；浓度越低时电离度越大，但电离常数不变，A错误。\nB．NaZ溶液中Kₕ＝c(HZ)·c(OH⁻)/c(Z⁻)。加少量盐酸后平衡移动，但温度不变，Kₕ不变，所以其倒数c(Z⁻)/[c(HZ)·c(OH⁻)]也不变，B错误。\nC．对一元弱酸，c(X⁻)可由初始浓度与电离度的乘积比较。按表中三组数据计算，c(X⁻)从左到右逐渐增大，C正确。\nD．同温、同浓度时，电离度越大，电离常数越大。由表中数据应有K₅＞K₄＞K₃，D错误。\n故选C。","expected_stem":"下表是在相同温度下三种酸的一些数据，下列判断正确的是\n提示：电离度＝n 电离（弱电解质）\nn 总（弱电解质）(\n)\n酸\nHX\nHY\nHZ\n浓度/(mol·L\n－1)\n0.12\n0.2\n0.9\n1\n1\n电离度\n0.25\n0.2\n0.1\n0.3\n0.5\n电离常数\nK1\nK2\nK3\nK4\nK5\nA.在相同温度下，由HX 的数据可以说明：弱电解质溶液，浓度越低，电离度越\n大，且K1>K2>K3＝0.01\n的值变大\nB.室温时，若在NaZ 溶液中加少量盐酸则\nc（Z\n－）\n－）\nc（HZ）·c（OH\nC.表格中三种浓度的HX 溶液中，从左至右c(X\n－)浓度逐渐增大\nD.在相同温度下，电离常数：K5<K4<K3","expected_options":["在相同温度下，由HX 的数据可以说明：弱电解质溶液，浓度越低，电离度越 大，且K1>K2>K3＝0.01 的值变大","室温时，若在NaZ 溶液中加少量盐酸则 c（Z －） －） c（HZ）·c（OH","表格中三种浓度的HX 溶液中，从左至右c(X －)浓度逐渐增大","在相同温度下，电离常数：K5<K4<K3"],"expected_content_fingerprint":"14fda18cdf24b31083d1c2fb07f9b2842bfb4516fb20904b54b287096a283282","audit_status":"PASS","segment_mode":"ABCD","required_markers":["A","B","C","D"],"new_asset_refs":[{"kind":"question_image","path":"h2orig/a9412d2fef20a8e3/21c5c19c49cffdc426d4926b05b4f891/question/r245be48b2999","alt":"苏教版高中化学原题14原题题面","sha256":"805946b83e5b0616dc011a03a0d79396ac554651753a5df1cb49869679bd80f8","width":1055,"height":620},{"kind":"analysis_image","path":"h2orig/a9412d2fef20a8e3/21c5c19c49cffdc426d4926b05b4f891/analysis/r245be48b2999","alt":"苏教版高中化学原题14原题解析","sha256":"616655570b854985d091a41561241fc104589a8d72dad3c99a55bb1731fa54a9","width":1055,"height":503}],"question_asset_sha256":"805946b83e5b0616dc011a03a0d79396ac554651753a5df1cb49869679bd80f8","analysis_asset_sha256":"616655570b854985d091a41561241fc104589a8d72dad3c99a55bb1731fa54a9","expected_revision_token":"836501b7c889e3e4502ca1888981f1aa9af8f7466f4a0939a8df16b9eaefda1f","expected_item_sha256":"e1875b65b5cde4620c3633f2e23d076252098433482e2554a710193848f1e0da","source_pdf_sha256":"1f43e3800520493d33ea368192d9402e19135115e6ba17639826216f81595943","question_png_sha256":"34561827ba60e12687937b6330c7f81aad42a3dca83909bf9cb9fe37f5e30cdc","analysis_png_sha256":"577bb08eefb54fa208e69f5a1d1a068833bf51ffa3f7b27a385e52e8d4f5f8f4"}]$full_visual_expected$::jsonb) as expected(
  source_manifest_id text,
  canonical_source_id text,
  grade_band text,
  skill_id text,
  old_question_id text,
  new_question_id text,
  correct_option smallint,
  baseline_explanation_sha256 text,
  expected_explanation_sha256 text,
  expected_explanation text,
  expected_stem text,
  expected_options jsonb,
  expected_content_fingerprint text,
  audit_status text,
  segment_mode text,
  required_markers text[],
