  question_asset_sha256 text,
  analysis_asset_sha256 text,
  expected_revision_token text,
  expected_item_sha256 text,
  source_pdf_sha256 text,
  question_png_sha256 text,
  analysis_png_sha256 text
);

alter table _full_visual_expected add primary key (source_manifest_id);
create unique index on _full_visual_expected(canonical_source_id);
create unique index on _full_visual_expected(old_question_id);
create unique index on _full_visual_expected(new_question_id);

-- Exact row snapshots for every table explicitly outside this migration's scope.
create temporary table _full_visual_h3_release_before on commit drop as
select r.id, to_jsonb(r) as row_data
from app_private.chem_question_source_releases r
where r.grade_band='高三';

create temporary table _full_visual_h3_question_before on commit drop as
select q.id, to_jsonb(q) as row_data
from public.chem_questions q
join app_private.chem_question_source_releases r on r.id=q.source_release_id
where r.grade_band='高三';

create temporary table _full_visual_plan_before on commit drop as
select p.id::text as id, to_jsonb(p) as row_data from public.chem_learning_plans p;
create temporary table _full_visual_attempt_before on commit drop as
select a.id::text as id, to_jsonb(a) as row_data from public.chem_learning_attempts a;
create temporary table _full_visual_answer_before on commit drop as
select a.id::text as id, to_jsonb(a) as row_data from public.chem_attempt_answers a;
create temporary table _full_visual_quiz_session_before on commit drop as
select q.id::text as id, to_jsonb(q) as row_data from public.quiz_sessions q;
create temporary table _full_visual_quiz_student_before on commit drop as
select s.id::text as id, to_jsonb(s) as row_data from public.students s;
create temporary table _full_visual_quiz_link_before on commit drop as
select to_jsonb(l) as row_data from public.chem_quiz_student_links l;

do $guard$
begin
  if (select count(*) from _full_visual_release_spec) <> 2
     or exists (
       select 1 from _full_visual_release_spec
       where (grade_band,expected_question_count) not in (('高一',125),('高二',200))
     )
  then
    raise exception 'full visual release specification is not H1=125/H2=200';
  end if;
  if (select count(*) from _full_visual_expected) <> 325
     or (select count(*) from _full_visual_expected where audit_status='PASS') <> 57
     or (select count(*) from _full_visual_expected where audit_status='FAIL') <> 268
     or exists (
       select 1 from _full_visual_expected
       where audit_status not in ('PASS','FAIL')
          or segment_mode not in ('ABCD','COMBINATION')
          or cardinality(required_markers) < 2
     )
  then
    raise exception 'full visual expected mapping is incomplete';
  end if;
  if exists (
    select 1
    from _full_visual_release_spec s
    left join app_private.chem_question_source_releases r
      on r.id=s.old_release_id
     and r.manifest_sha256=s.old_manifest_sha256
     and r.grade_band=s.grade_band
     and r.status='active'
     and r.verification_status='full_visual_verified'
     and r.revision_contract='v1_assets'
    where r.id is null
  ) then
    raise exception 'active H1/H2 baseline differs from the hash-bound audited release';
  end if;
  if exists (
    select 1 from _full_visual_release_spec s
    join app_private.chem_question_source_releases r
      on r.id=s.new_release_id or r.manifest_sha256=s.new_manifest_sha256
  ) then
    raise exception 'a replacement release identity already exists';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join _full_visual_release_spec s on s.grade_band=e.grade_band
    left join public.chem_questions q
      on q.id=e.old_question_id and q.source_release_id=s.old_release_id
    left join app_private.chem_question_source_release_items ri
      on ri.release_id=s.old_release_id
     and ri.question_id=e.old_question_id
     and ri.canonical_source_id=e.canonical_source_id
    where q.id is null
       or ri.question_id is null
       or q.skill_id is distinct from e.skill_id
       or q.correct_option is distinct from e.correct_option
       or ri.question_asset_sha256 is distinct from e.question_asset_sha256
       or ri.analysis_asset_sha256 is distinct from e.analysis_asset_sha256
       or pg_catalog.encode(extensions.digest(pg_catalog.convert_to(q.explanation,'UTF8'),'sha256'),'hex')
            is distinct from e.baseline_explanation_sha256
  ) then
    raise exception 'an audited row does not match the active source/answer/explanation/image hashes';
  end if;
  if exists (
    select 1
    from _full_visual_release_spec s
    left join lateral (
      select count(*) questions from public.chem_questions q where q.source_release_id=s.old_release_id
    ) q_count on true
    left join lateral (
      select count(*) items from app_private.chem_question_source_release_items ri where ri.release_id=s.old_release_id
    ) i_count on true
    left join lateral (
      select count(*) assets
      from app_private.chem_question_assets a
      join public.chem_questions q on q.id=a.question_id
      where q.source_release_id=s.old_release_id
    ) a_count on true
    where q_count.questions<>s.expected_question_count
       or i_count.items<>s.expected_question_count
       or a_count.assets<>s.expected_question_count*2
  ) then
    raise exception 'active H1/H2 source inventory is incomplete';
  end if;
end;
$guard$;

insert into app_private.chem_question_source_releases(
  id,manifest_sha256,grade_band,status,expected_question_count,
  verification_status,revision_contract
)
select
  new_release_id,new_manifest_sha256,grade_band,'staged',expected_question_count,
  'pending','v2_explanation_assets'
from _full_visual_release_spec;

insert into public.chem_questions(
  id,mother_id,skill_id,level,grade_band,
  stem,options,correct_option,explanation,scaffold,
  review_status,scope_status,source_kind,image_url,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint,
  concept_key,source_info,asset_refs,render_mode,
  source_item_key,content_fingerprint,question_revision_token,
  source_release_id,usable_for_demo
)
select
  e.new_question_id,q.mother_id,q.skill_id,q.level,q.grade_band,
  e.expected_stem,e.expected_options,
  q.correct_option,e.expected_explanation,null,
  'approved','IN','licensed_local',null,
  false,false,false,
  q.concept_key,q.source_info,e.new_asset_refs,'image_primary',
  q.source_item_key,e.expected_content_fingerprint,e.expected_revision_token,
  s.new_release_id,false
from _full_visual_expected e
join _full_visual_release_spec s on s.grade_band=e.grade_band
join public.chem_questions q
  on q.id=e.old_question_id and q.source_release_id=s.old_release_id;

insert into app_private.chem_question_assets(
  asset_path,question_id,asset_kind,mime_type,
  payload_base64,sha256,width,height
)
select
  new_ref.ref->>'path',e.new_question_id,a.asset_kind,a.mime_type,
  a.payload_base64,a.sha256,a.width,a.height
from _full_visual_expected e
join app_private.chem_question_assets a on a.question_id=e.old_question_id
join lateral (
  select ref
  from pg_catalog.jsonb_array_elements(e.new_asset_refs) ref
  where ref->>'kind'=a.asset_kind
) new_ref on true;

insert into app_private.chem_question_source_release_items(
  release_id,question_id,canonical_source_id,
  question_asset_sha256,analysis_asset_sha256,item_sha256
)
select
  s.new_release_id,q.id,e.canonical_source_id,
  e.question_asset_sha256,e.analysis_asset_sha256,
  app_private.chem_h3_release_item_sha256(
    q,e.canonical_source_id,e.question_asset_sha256,e.analysis_asset_sha256
  )
from _full_visual_expected e
join _full_visual_release_spec s on s.grade_band=e.grade_band
join public.chem_questions q on q.id=e.new_question_id;

do $qa$
declare
  v_manifest text;
  v_spec record;
begin
  if (select count(*) from public.chem_questions q join _full_visual_release_spec s on s.new_release_id=q.source_release_id) <> 325
     or (select count(*) from app_private.chem_question_assets a join _full_visual_expected e on e.new_question_id=a.question_id) <> 650
     or (select count(*) from app_private.chem_question_source_release_items ri join _full_visual_release_spec s on s.new_release_id=ri.release_id) <> 325
  then
    raise exception 'replacement release inventory is not 325 questions/650 assets/325 ledger rows';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join _full_visual_release_spec s on s.grade_band=e.grade_band
    join public.chem_questions old_q on old_q.id=e.old_question_id and old_q.source_release_id=s.old_release_id
    join public.chem_questions new_q on new_q.id=e.new_question_id and new_q.source_release_id=s.new_release_id
    where new_q.mother_id is distinct from old_q.mother_id
       or new_q.skill_id is distinct from old_q.skill_id
       or new_q.concept_key is distinct from old_q.concept_key
       or new_q.level is distinct from old_q.level
       or new_q.grade_band is distinct from old_q.grade_band
       or new_q.stem is distinct from e.expected_stem
       or new_q.options is distinct from e.expected_options
       or new_q.correct_option is distinct from old_q.correct_option
       or new_q.source_info is distinct from old_q.source_info
       or new_q.source_item_key is distinct from old_q.source_item_key
       or new_q.content_fingerprint is distinct from e.expected_content_fingerprint
       or new_q.explanation is distinct from e.expected_explanation
       or new_q.asset_refs is distinct from e.new_asset_refs
       or new_q.scaffold is not null
       or new_q.image_url is not null
       or new_q.review_status<>'approved'
       or new_q.scope_status<>'IN'
       or new_q.source_kind<>'licensed_local'
       or new_q.render_mode<>'image_primary'
       or new_q.usable_for_review
       or new_q.usable_for_class_quiz
       or new_q.usable_for_exam_sprint
       or new_q.usable_for_demo
  ) then
    raise exception 'a replacement question differs outside immutable identity/explanation paths';
  end if;
  if (
    select count(*)
    from _full_visual_expected e
    join public.chem_questions old_q on old_q.id=e.old_question_id
    join public.chem_questions new_q on new_q.id=e.new_question_id
    where new_q.explanation is distinct from old_q.explanation
  ) <> 268
  then
    raise exception 'replacement release must change exactly 268 FAIL explanations';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join public.chem_questions old_q on old_q.id=e.old_question_id
    join public.chem_questions new_q on new_q.id=e.new_question_id
    where (e.audit_status='PASS' and new_q.explanation is distinct from old_q.explanation)
       or (e.audit_status='FAIL' and new_q.explanation is not distinct from old_q.explanation)
       or pg_catalog.encode(extensions.digest(pg_catalog.convert_to(new_q.explanation,'UTF8'),'sha256'),'hex')
            is distinct from e.expected_explanation_sha256
  ) then
    raise exception 'PASS byte preservation or FAIL hash binding failed';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join public.chem_questions q on q.id=e.new_question_id
    where position('N' || chr(8336) in q.stem || q.options::text || q.explanation) > 0
       or position('Vₘ' in q.stem || q.options::text || q.explanation) > 0
       or q.explanation ~ '(学科网|股份有限公司|原题来源|来源[：:]|题面PDF|解析PDF|原解析图|下一题|物理页[[:space:]]*[0-9]+|练[·・]高考真题|题组[一二三四五六七八九十]|�|[-])'
  ) then
    raise exception 'forbidden notation, source/page text, garbling, or cross-question fragment remains';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join public.chem_questions q on q.id=e.new_question_id
    where e.segment_mode='ABCD'
      and not (
        coalesce(nullif(strpos(q.explanation,'A．'),0),nullif(strpos(q.explanation,'A 项'),0),nullif(strpos(q.explanation,'A项'),0),0) > 0
        and coalesce(nullif(strpos(q.explanation,'B．'),0),nullif(strpos(q.explanation,'B 项'),0),nullif(strpos(q.explanation,'B项'),0),0)
            > coalesce(nullif(strpos(q.explanation,'A．'),0),nullif(strpos(q.explanation,'A 项'),0),nullif(strpos(q.explanation,'A项'),0),0)
        and coalesce(nullif(strpos(q.explanation,'C．'),0),nullif(strpos(q.explanation,'C 项'),0),nullif(strpos(q.explanation,'C项'),0),0)
            > coalesce(nullif(strpos(q.explanation,'B．'),0),nullif(strpos(q.explanation,'B 项'),0),nullif(strpos(q.explanation,'B项'),0),0)
        and coalesce(nullif(strpos(q.explanation,'D．'),0),nullif(strpos(q.explanation,'D 项'),0),nullif(strpos(q.explanation,'D项'),0),0)
            > coalesce(nullif(strpos(q.explanation,'C．'),0),nullif(strpos(q.explanation,'C 项'),0),nullif(strpos(q.explanation,'C项'),0),0)
      )
  ) then
    raise exception 'an ordinary single-choice explanation lacks ordered A/B/C/D segments';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join public.chem_questions q on q.id=e.new_question_id
    where e.segment_mode='COMBINATION'
      and exists (
        select 1
        from (
          select ordinal, strpos(q.explanation,marker) as marker_position,
                 lag(strpos(q.explanation,marker)) over(order by ordinal) as previous_position
          from unnest(e.required_markers) with ordinality as required(marker,ordinal)
        ) positions
        where marker_position=0
           or (previous_position is not null and marker_position<=previous_position)
      )
  ) then
    raise exception 'a combination question lacks ordered statement-by-statement analysis';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join app_private.chem_question_assets old_a on old_a.question_id=e.old_question_id
    left join app_private.chem_question_assets new_a
      on new_a.question_id=e.new_question_id and new_a.asset_kind=old_a.asset_kind
    join lateral (
      select ref from jsonb_array_elements(e.new_asset_refs) ref
      where ref->>'kind'=old_a.asset_kind
    ) expected_ref on true
    where new_a.asset_path is null
       or new_a.asset_path is distinct from expected_ref.ref->>'path'
       or new_a.mime_type is distinct from old_a.mime_type
       or new_a.payload_base64 is distinct from old_a.payload_base64
       or new_a.sha256 is distinct from old_a.sha256
       or new_a.width is distinct from old_a.width
       or new_a.height is distinct from old_a.height
  ) then
    raise exception 'a private source asset differs from the visually verified bytes';
  end if;
  if exists (
    select 1
    from _full_visual_expected e
    join _full_visual_release_spec s on s.grade_band=e.grade_band
    join public.chem_questions q on q.id=e.new_question_id
    join app_private.chem_question_assets qa on qa.question_id=q.id and qa.asset_kind='question_image'
    join app_private.chem_question_assets aa on aa.question_id=q.id and aa.asset_kind='analysis_image'
    join app_private.chem_question_source_release_items ri on ri.release_id=s.new_release_id and ri.question_id=q.id
    where q.question_revision_token is distinct from e.expected_revision_token
       or q.question_revision_token is distinct from app_private.chem_h3_question_revision_sha256(q,qa.sha256,aa.sha256)
       or ri.item_sha256 is distinct from e.expected_item_sha256
       or ri.item_sha256 is distinct from app_private.chem_h3_release_item_sha256(q,e.canonical_source_id,qa.sha256,aa.sha256)
       or ri.question_asset_sha256 is distinct from qa.sha256
       or ri.analysis_asset_sha256 is distinct from aa.sha256
  ) then
    raise exception 'v2 revision token, release ledger, or asset digest mismatch';
  end if;
  for v_spec in select * from _full_visual_release_spec order by grade_band loop
    select pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(pg_catalog.string_agg(ri.item_sha256,E'\n' order by ri.question_id),'UTF8'),
        'sha256'
      ),
      'hex'
    ) into v_manifest
    from app_private.chem_question_source_release_items ri
    where ri.release_id=v_spec.new_release_id;
    if v_manifest is distinct from v_spec.new_manifest_sha256 then
      raise exception '% manifest is %, expected %',v_spec.grade_band,v_manifest,v_spec.new_manifest_sha256;
    end if;
  end loop;
end;
$qa$;

select public.chem_mark_source_original_release_visually_verified(
  new_release_id,new_manifest_sha256,'codex-full-visual-qa'
)
from _full_visual_release_spec
order by grade_band;

do $activate$
declare v_spec record;
begin
  for v_spec in select * from _full_visual_release_spec order by grade_band loop
    perform public.chem_activate_source_original_release(v_spec.new_release_id,v_spec.new_manifest_sha256);
  end loop;
end;
$activate$;

do $postcondition$
begin
  if exists (
    select 1
    from _full_visual_release_spec s
    left join app_private.chem_question_source_releases new_r
      on new_r.id=s.new_release_id and new_r.status='active'
     and new_r.verification_status='full_visual_verified'
     and new_r.revision_contract='v2_explanation_assets'
    left join app_private.chem_question_source_releases old_r
      on old_r.id=s.old_release_id and old_r.status='retired'
    where new_r.id is null or old_r.id is null
  ) then
    raise exception 'replacement activation/retained rollback release postcondition failed';
  end if;
  if exists (
    select 1
    from _full_visual_release_spec s
    left join lateral (
      select count(*) enabled
      from public.chem_questions q
      where q.source_release_id=s.new_release_id and q.usable_for_review
    ) enabled_count on true
    where enabled_count.enabled<>s.expected_question_count
  ) then
    raise exception 'activated H1/H2 usable question inventory is not 125/200';
  end if;
  if (select count(*) from app_private.chem_question_source_releases where grade_band='高三')
       <> (select count(*) from _full_visual_h3_release_before)
     or exists (
       select 1 from _full_visual_h3_release_before snapshot
       left join app_private.chem_question_source_releases r on r.id=snapshot.id
       where r.id is null or to_jsonb(r) is distinct from snapshot.row_data
     )
     or (select count(*) from public.chem_questions q join app_private.chem_question_source_releases r on r.id=q.source_release_id where r.grade_band='高三')
       <> (select count(*) from _full_visual_h3_question_before)
     or exists (
       select 1 from _full_visual_h3_question_before snapshot
       left join public.chem_questions q on q.id=snapshot.id
       where q.id is null or to_jsonb(q) is distinct from snapshot.row_data
     )
  then
    raise exception 'H3 release/question rows changed unexpectedly';
  end if;
  if (select count(*) from public.chem_learning_plans)<>(select count(*) from _full_visual_plan_before)
     or exists (select 1 from _full_visual_plan_before s left join public.chem_learning_plans p on p.id::text=s.id where p.id is null or to_jsonb(p) is distinct from s.row_data)
     or (select count(*) from public.chem_learning_attempts)<>(select count(*) from _full_visual_attempt_before)
     or exists (select 1 from _full_visual_attempt_before s left join public.chem_learning_attempts a on a.id::text=s.id where a.id is null or to_jsonb(a) is distinct from s.row_data)
     or (select count(*) from public.chem_attempt_answers)<>(select count(*) from _full_visual_answer_before)
     or exists (select 1 from _full_visual_answer_before s left join public.chem_attempt_answers a on a.id::text=s.id where a.id is null or to_jsonb(a) is distinct from s.row_data)
  then
    raise exception 'REVIEW plans, attempts, or answer history changed unexpectedly';
  end if;
  if (select count(*) from public.quiz_sessions)<>(select count(*) from _full_visual_quiz_session_before)
     or exists (select 1 from _full_visual_quiz_session_before s left join public.quiz_sessions q on q.id::text=s.id where q.id is null or to_jsonb(q) is distinct from s.row_data)
     or (select count(*) from public.students)<>(select count(*) from _full_visual_quiz_student_before)
     or exists (select 1 from _full_visual_quiz_student_before s left join public.students q on q.id::text=s.id where q.id is null or to_jsonb(q) is distinct from s.row_data)
     or (select count(*) from public.chem_quiz_student_links)<>(select count(*) from _full_visual_quiz_link_before)
     or exists (
       (select row_data from _full_visual_quiz_link_before except all select to_jsonb(l) from public.chem_quiz_student_links l)
       union all
       (select to_jsonb(l) from public.chem_quiz_student_links l except all select row_data from _full_visual_quiz_link_before)
     )
  then
    raise exception 'independent quiz students, links, or sessions changed unexpectedly';
  end if;
end;
$postcondition$;

commit;
